head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS24600.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명 : 발행등록사실확인 목록 조회
 ***********************************************/
scwin.fn_Search = function() {
    if (!$c.stf.compareFromToDate2(edt_FromDt, edt_ToDt)) {
        return;
    }
    dts_List1.removeAll();
    var param = '';
    param += "&{P}V_STD_CD=" + $c.stf.getObjectValue(txb_StdCd); //표준코드
    param += "&{P}V_ISU_NM=" + $c.stf.getObjectValue(txb_IsuNm); //종목명
    param += "&{P}V_FROM_DT=" + $c.stf.getObjectValue(edt_FromDt); //From Date
    param += "&{P}V_TO_DT=" + $c.stf.getObjectValue(edt_ToDt); //To Date

    var dsNm = 'BNS_ISU_REG_FACT_CONFRM_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectIsuRegFactConfrmList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List1, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List1);
};


/********************************************** 
 * 설명 : 예탁원 발행등록내역 조회
 ***********************************************/
scwin.fn_Search1 = function() {
    dts_List2.removeAll();
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var ksd_reg_dd = dts_List1.getCellData(dts_List1.getRowPosition(), "KSD_REG_DD"); // 등록일자

    var param = '';
    param += "&{P}V_STD_CD=" + std_cd; //표준코드
    param += "&{P}V_FROM_DT=" + ksd_reg_dd; //행사일자
    param += "&{P}V_TO_DT=" + ksd_reg_dd; //행사일자

    var dsNm = 'BNS_KSD_RER_FACT_RCV_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectKsdRegFactRcvList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List2, dsNm, qryId, param);
};



/********************************************** 
 * 설명 : 채권신고담당자 조회
 ***********************************************/
scwin.fn_Search2 = function() {
    dts_List3.removeAll();
    var isur_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List3, dsNm, qryId, param);
};



/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: $c.stf.getObjectValue(txb_IsuNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_StdCd, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].ISU_NM);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_List1.getCellData(dts_List1.getRowPosition(), "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_List1.getCellData(dts_List1.getRowPosition(), "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_KsdApiCall
 * 설명       : 예탁원 API를 Call 하여 발행등록사실확인정보를 가져온다.
 ***********************************************/
scwin.fn_KsdApiCall = function() {
    if ($c.stf.getObjectValue(edt_FromDt) == "" || $c.stf.getObjectValue(edt_ToDt) == "") {
        $c.win.alert("상장일자를 입력하세요.");
        return;
    }
    if (!confirm("예탁원 발행등록사실확인정보를 요청하시겠습니까?")) return;
    var url;
    url = "/MktVerifSystem.do?method=recvKsdIsuRegFactReq";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 파라미터 세팅
    var param = "FROM_DT=" + $c.stf.getObjectValue(edt_FromDt);
    param += ", TO_DT=" + $c.stf.getObjectValue(edt_ToDt);
    param += ", ISSU_REGI_SEC_TP_CD=11"; // 채권 고정
    param += ", ISIN=" + $c.stf.getObjectValue(txb_StdCd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_CallDt)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetSearchDt
 * 설명      : 조회조건 구하기.. 현재일로부터 영업일기준으로 T-1 ~ T+2 일
 ***********************************************/
scwin.fn_SetSearchDt = function() {
    var base_dt = $c.ut.cGetToday2();
    var offPrev = 1;
    var offNext = 1;
    $c.bns.getBusinessDay(scwin.vScrenID, dts_BizDt, base_dt, offPrev, offNext);
    edt_FromDt.setValue(dts_BizDt.getCellData(1, "FROM_DT"));
    edt_ToDt.setValue(dts_BizDt.getCellData(1, "TO_DT"));
};


/********************************************** 
 * 함수명   : fn_GetKsdApiCallDt
 * 설명      : 예탁원발행등록사실정보 api 최근 호출일 조회
 ***********************************************/
scwin.fn_GetKsdApiCallDt = function() {
    var param = '';
    param += "&{P}V_CASE=ISU_REG";
    var dsNm = 'BNS_KSD_ISU_REG_CALL_DT';
    var qryId = 'lds.stf.bnsdecl_mgr.select.getMaxCallDt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CallDt, dsNm, qryId, param);
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(panel_Top);
    $c.bns.BnsPanelToGroupBox(panel_1);

    // 상장일자 기본 세팅, 오늘+1일
    scwin.fn_SetSearchDt();

    // 예탁원발행등록사실정보 api 최근 호출일 조회
    scwin.fn_GetKsdApiCallDt();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_List1_OnRowPosChanged = function(row) {
    if (dts_List1.getTotalRow() < 1) return;
    scwin.fn_Search1();
    scwin.fn_Search2();
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List1);
    dts_List2.removeAll();
    dts_List3.removeAll();
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    //CloseWin(rowcount, grd_List2); 

};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    //CloseWin(rowcount, grd_List3); 

};
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    scwin.fn_GetPar = fn_GetParListBndIsu;
    scwin.fn_SetPar = fn_SetParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
};
scwin.txb_StdCd_onkeypress = function() {
    if (window.event.keyCode == 13 && $c.stf.getObjectValue(txb_StdCd) != "") {
        scwin.fn_Search();
    }
};
scwin.txb_StdCd_onchange = function() {
    $c.stf.setObjectValue(txb_IsuNm, "");
};
scwin.txb_IsuNm_onchange = function() {
    $c.stf.setObjectValue(txb_StdCd, "");
};
scwin.txb_IsuNm_onkeypress = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_GetPar = fn_GetParListBndIsu;
        scwin.fn_SetPar = fn_SetParListBndIsu;
        $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
    }
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_FromDt);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_ToDt);
};
scwin.dts_List1_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List2_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List3_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.grd_List1_OnDblClick = function(row, colid) {
    var payCertYn = dts_List1.getCellData(dts_List1.getRowPosition(), "PAY_CERT_YN");
    if (colid == "PAY_CERT_YN") {
        scwin.fn_GetPar = fn_GetCommonKey;
        $c.bns.fn_PopAttachDocSearch(grd_List1);
    }
};
scwin.btn_Call_onclick = function() {
    scwin.fn_KsdApiCall();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
    scwin.fn_Search();

    // 예탁원발행등록사실정보 api 최근 호출일 조회
    scwin.fn_GetKsdApiCallDt();
};
scwin.dts_CallDt_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txt_CallDt, dts_CallDt.getCellData(1, "CALL_DT"));
};
